entries[31501] = { ["name"] = "Foliant des Essenherbeizauberns VIII", ["text"] = "Klassen: Magier\nBenötigt Stufe 70\nBenutzen: Lehrt 'Essen herbeizaubern' (Rang 8).\nZaubert 20 Croissants herbei und versorgt den Magier sowie seine Verbündeten mit etwas Essbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nHerbeigezaubertes Croissant\nHerbeigezauberter Gegenstand\nBenötigt Stufe 65\nBenutzen: Stellt im Verlauf von 30 sec insgesamt 7500 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
